// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, GorillaServerOptions{})
}

type GorillaServerOptions struct {
	BaseURL          string
	BaseRouter       *mux.Router
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, r *mux.Router) http.Handler {
	return HandlerWithOptions(si, GorillaServerOptions{
		BaseRouter: r,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, r *mux.Router, baseURL string) http.Handler {
	return HandlerWithOptions(si, GorillaServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options GorillaServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = mux.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.HandleFunc(options.BaseURL+"/api/v1/patients", wrapper.ListPatients).Methods(http.MethodGet)

	r.HandleFunc(options.BaseURL+"/api/v1/patients", wrapper.CreatePatient).Methods(http.MethodPost)

	r.HandleFunc(options.BaseURL+"/api/v1/patients/{id}", wrapper.DeletePatient).Methods(http.MethodDelete)

	r.HandleFunc(options.BaseURL+"/api/v1/patients/{id}", wrapper.GetPatient).Methods(http.MethodGet)

	r.HandleFunc(options.BaseURL+"/api/v1/patients/{id}", wrapper.UpdatePatient).Methods(http.MethodPut)

	r.HandleFunc(options.BaseURL+"/api/v1/patients/{id}/record", wrapper.GetPatientRecord).Methods(http.MethodGet)

	r.HandleFunc(options.BaseURL+"/api/v1/patients/{id}/record", wrapper.CreateRecord).Methods(http.MethodPost)

	r.HandleFunc(options.BaseURL+"/api/v1/records/{id}", wrapper.GetRecord).Methods(http.MethodGet)

	r.HandleFunc(options.BaseURL+"/api/v1/records/{id}/changes", wrapper.SaveRecord).Methods(http.MethodPost)

	r.HandleFunc(options.BaseURL+"/api/v1/records/{id}/history", wrapper.GetRecordHistory).Methods(http.MethodGet)

	r.HandleFunc(options.BaseURL+"/api/v1/records/{id}/state", wrapper.GetRecordState).Methods(http.MethodGet)

	return r
}

